    static var routines: [Routine] {
        let templates: [(String, [String])] = [
            ("Full Body A", ["Sentadilla barra", "Press banca barra", "Remo polea sentado", "Peso muerto rumano", "Plancha"]),
            ("Torso A", ["Press banca barra", "Jalon al pecho", "Press hombro mancuernas", "Remo polea sentado", "Curl barra", "Extension triceps polea"]),
            ("Pierna A", ["Sentadilla barra", "Peso muerto rumano", "Prensa de piernas", "Curl femoral sentado", "Gemelo de pie"]),
            ("Empuje", ["Press banca barra", "Press inclinado mancuernas", "Press hombro mancuernas", "Elevacion lateral", "Extension triceps polea"]),
            ("Tirón", ["Jalon al pecho", "Remo barra", "Remo polea sentado", "Face pull", "Curl barra", "Curl martillo"]),
            ("Solo mancuernas", ["Press banca mancuernas", "Remo mancuerna", "Zancadas", "Press hombro mancuernas", "Curl martillo"]),
        ]
        return templates.enumerated().map { index, template in
            Routine(id: "seed-routine-\(index)", name: template.0, notes: "Plantilla editable. Ajusta ejercicios, series, repeticiones y descansos a tu plan.", exercises: template.1.compactMap { name in
                guard let exercise = all.first(where: { $0.name == name }) else { return nil }
                let sets = (0..<3).map { _ in name == "Plancha" ? WorkoutSet(reps: 0, durationSeconds: 30) : WorkoutSet() }
                return WorkoutExercise(exerciseId: exercise.id, exerciseName: name, sets: sets)
            })
        }
    }
    static var initialData: GymData { GymData(exercises: all, routines: routines) }
